import { createTRPCClient, createWSClient, httpBatchLink, httpSubscriptionLink, splitLink, wsLink } from '@trpc/client'
import type { AppRouter } from '../generated/appRouter'

// The NestJS backend. Same-origin in both dev and prod: in dev Vite proxies `/trpc` to the server; in
// prod Nest serves this bundle and `/trpc` on one port. So the client uses relative URLs - no
// VITE_API_URL, no CORS. The AppRouter type is generated by the server's typegen adapter on boot.
//
// Transports. Queries and mutations go over the batched HTTP link. A live feed (a subscription that
// stays open while the page is) passes `context: LIVE_FEED` and shares this tab's one WebSocket:
// browsers allow six HTTP/1.1 connections per host across all tabs of a profile, so one SSE stream
// per feed per tab starves the next tab, while WebSockets do not count against that limit. Other
// subscriptions are one-shot action streams (run now, verify) and stay on SSE, because the socket
// client re-sends open subscriptions after a reconnect, which would start the action again.
// The same /trpc path serves all three (server: apps/server/src/trpc/trpc-socket.ts).
// CSRF: the server requires this header on cookie-authed mutations (see auth.guard.ts). Sending it on
// every tRPC call is harmless (queries ignore it) and covers all mutations. Bearer clients are exempt.
// The socket has no headers; the server accepts its upgrade only from this origin instead.
const CSRF_HEADERS = { 'x-box-csrf': '1' }

/** Pass as a live feed's `context` to carry it over the tab's WebSocket. A reconnect re-subscribes
 *  with the original input, so the feed must resync itself (a hello frame, a cursor). */
export const LIVE_FEED = { liveFeed: true }

const socket = createWSClient({
  url: () => `${location.protocol === 'https:' ? 'wss' : 'ws'}://${location.host}/trpc`,
  // Opened by the first feed and closed shortly after the last one stops (a hidden tab's feeds stop).
  lazy: { enabled: true, closeMs: 5_000 },
  // Client pings notice a dead socket (a laptop waking, a network change) and reconnect.
  keepAlive: { enabled: true, intervalMs: 20_000, pongTimeoutMs: 5_000 },
  retryDelayMs: (attempt) => Math.min(500 * 2 ** attempt, 10_000),
})

export const trpc = createTRPCClient<AppRouter>({
  links: [
    splitLink({
      condition: (op) => op.type === 'subscription',
      true: splitLink({
        condition: (op) => op.context.liveFeed === true,
        true: wsLink({ client: socket }),
        false: httpSubscriptionLink({ url: '/trpc' }),
      }),
      false: httpBatchLink({ url: '/trpc', headers: () => CSRF_HEADERS }),
    }),
  ],
})
